import os
from datetime import timedelta
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.collectors.collect_tti import TtiCollector, remove_old_tti_files
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console
from apscheduler.schedulers.background import BackgroundScheduler  # type: ignore
from taf.ul.sc.perf.util.test_duration_manager import TestDurationManager


@log_function_status_to_console(msg="Collect tti traces", log_hierarchy=2)
@log_debug_function_info()
def collect_tti_traces():
    bts = perf.tl.main_bts
    alias = tc.run_params['collect_tti_traces']['tti_alias']
    tti_collection_interval = tc.run_params['collect_tti_traces']['tti_collection_interval']

    remove_old_tti_files(log_dir=tc.output_dir,
                         debug_tti_dir=os.path.join(tc.output_dir, 'debug', bts.name, 'tti'),
                         dir_pattern='{}*'.format(alias))

    if bts.ems:
        tti_scheduler = BackgroundScheduler()
        cells_info = bts.get_bts_cells_info()

        for index, tti_trigger in enumerate(tc.run_params['collect_tti_traces']['tti_time_triggers']):
            if (tti_trigger + tti_collection_interval) < tc.run_params['duration']:
                tti_collector = TtiCollector(bts_name=bts.name, cells_names=cells_info['cells_id'],
                                             alias='{}_{}'.format(alias, index + 1),
                                             tti_collection_interval=tti_collection_interval,
                                             output_dir=tc.output_dir)
                run_date = TestDurationManager().execution_start + timedelta(seconds=float(tti_trigger))
                tti_scheduler.add_job(func=tti_collector.trigger_tti_collection,
                                      kwargs={'sample_id': index + 1, 'add_tti_stats': True},
                                      trigger='date',
                                      run_date=run_date)
                if tti_scheduler.state == 0:
                    tti_scheduler.start()
    else:
        MolerTest.error(msg='TTI functionality needs EMS device to get cells id.')
